package ktanesolver.module.modded.regular.hogwarts;
import static org.assertj.core.api.Assertions.assertThat;import java.util.List;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class HogwartsSolverTest{@Test void scoresFounderLetterIntersectionsAndReportsAllTiedWinners(){var r=new HogwartsSolver().solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new HogwartsInput(List.of(new HogwartsEntry("Wires","Gryffindor"),new HogwartsEntry("Memory","Ravenclaw"),new HogwartsEntry("Button","Slytherin"),new HogwartsEntry("Maze","Hufflepuff"))));var o=((SolveSuccess<HogwartsOutput>)r).output();assertThat(o.selections()).hasSize(4);assertThat(o.winningHouses()).isNotEmpty();assertThat(HogwartsSolver.points("Wires","GODRICGRYFFINDOR")).isPositive();}}
